const sigmoid = (z) => 1 / (1 + Math.exp(-z));

function toFinite(value, fallback) {
  const num = Number(value);
  return Number.isFinite(num) ? num : fallback;
}

/**
 * Run OA inference on a 7-feature vector (order = FEATURE_NAMES).
 * Missing/NaN entries fall back to healthy-neutral values.
 * Returns probability of knee OA in the open interval (0, 1).
 */
export function predictOAProbability(features) {
  let z = MODEL_INTERCEPT;
  for (let i = 0; i < MODEL_WEIGHTS.length; i += 1) {
    const x = toFinite(features?.[i], HEALTHY_NEUTRAL[i]);
    z += MODEL_WEIGHTS[i] * ((x - SCALER_MEAN[i]) / SCALER_SCALE[i]);
  }
  return sigmoid(z);
}

/**
 * Per-feature risk contribution breakdown for UI explanations.
 * Returns one entry per feature: how much it pushes the OA probability up
 * or down (log-odds units), plus the standardized value.
 */
export function explainFeatures(features) {
  return FEATURE_NAMES.map((name, i) => {
    const raw = toFinite(features?.[i], HEALTHY_NEUTRAL[i]);
    const standardized = (raw - SCALER_MEAN[i]) / SCALER_SCALE[i];
    const contribution = MODEL_WEIGHTS[i] * standardized;
    return {
      name,
      raw,
      standardized,
      contribution,
      increasesRisk: contribution > 0,
    };
  });
}

export default { predictOAProbability, explainFeatures };
